def transform(grid):
    from collections import Counter, deque
    h,w=len(grid),len(grid[0]); bg=Counter(x for row in grid for x in row).most_common(1)[0][0]
    seen=set(); objs=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c]==bg or (r,c) in seen:continue
            color=grid[r][c]; q=[(r,c)]; seen.add((r,c)); cells=[]
            for y,x in q:
                cells.append((y,x))
                for dy,dx in [(1,0),(-1,0),(0,1),(0,-1)]:
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and grid[yy][xx]==color and (yy,xx) not in seen:
                        seen.add((yy,xx));q.append((yy,xx))
            objs.append((color,cells))
    color5,cells5=next((co,cs) for co,cs in objs if co==5)
    ys=[r for r,c in cells5];xs=[c for r,c in cells5]
    marker=next(co for co,cs in objs if co not in (bg,5) and len(cs)<=6 and co in (3,9))
    return [[5 if r in (min(ys),max(ys)) and c in (min(xs),max(xs)) or r==min(ys)+1 or c in (min(xs),max(xs)) else marker for c in range(min(xs),max(xs)+1)] for r in range(min(ys),max(ys)+1)]
